### Additional Information

## Reproduction example:

```js
const { app, BrowserWindow, WebContentsView } = require('electron');

let mainWindow;
let contextView;

function createWindow() {
  mainWindow = new BrowserWindow({
    width: 800,
    height: 600,
    webPreferences: {
      nodeIntegration: true,
      contextIsolation: false
    }
  });

  contextView = new WebContentsView({
    webPreferences: {
      nodeIntegration: true,
      contextIsolation: false
    }
  });

  mainWindow.contentView.addChildView(contextView)

  const bounds = mainWindow.getBounds();
  contextView.setBounds({
    x: 0,
    y: 0,
    width: bounds.width,
    height: bounds.height
  });

  contextView.webContents.loadURL('https://electronjs.org');

  mainWindow.maximize();
}

app.whenReady().then(() => {
  createWindow();
});

```

