```
import { useState, useRef } from 'react'
import Versions from './components/Versions'
import electronLogo from './assets/electron.svg'

type Position = {
  x: number
  y: number
}

function App(): React.JSX.Element {
  const [position, setPosition] = useState<Position>({ x: 0, y: 0 })
  const [dragging, setDragging] = useState<boolean>(false)
  const dragStart = useRef<Position>({ x: 0, y: 0 })
  const mouseStart = useRef<Position>({ x: 0, y: 0 })

  const handleMouseDown = (e: React.MouseEvent<HTMLImageElement, MouseEvent>) => {
    setDragging(true)
    dragStart.current = { ...position }
    mouseStart.current = { x: e.clientX, y: e.clientY }
    // Prevent default to avoid unwanted drag image
    e.preventDefault()
  }

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement, MouseEvent>) => {
    if (!dragging) return
    const dx = e.clientX - mouseStart.current.x
    const dy = e.clientY - mouseStart.current.y
    setPosition({
      x: dragStart.current.x + dx,
      y: dragStart.current.y + dy
    })
  }

  const handleMouseUp = () => {
    setDragging(false)
  }

  return (
    <div
      style={{
        width: '100vw',
        height: '100vh',
        position: 'relative',
        userSelect: 'none'
      }}
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseUp}
    >
      <img
        alt="logo"
        className="logo"
        src={electronLogo}
        style={{
          position: 'absolute',
          left: position.x,
          top: position.y,
          cursor: dragging ? 'grabbing' : 'grab',
          // Remove WebkitAppRegion for custom drag
          // WebkitAppRegion: 'drag', // removed
        }}
        draggable={false}
        onMouseDown={handleMouseDown}
      />
      <Versions />
    </div>
  )
}

export default App


```
